-- pos-customer: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.commercial_party (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    party_type smallint NOT NULL,
    status smallint NOT NULL,
    tier smallint NOT NULL,
    tier_manual_override boolean NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    tier_assigned_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    customer_id uuid NOT NULL,
    parent_party_id uuid,
    billing_terms_id character varying(255),
    customer_number character varying(255) NOT NULL,
    display_name character varying(255),
    legal_name character varying(255) NOT NULL,
    primary_address character varying(255),
    tax_id character varying(255),
    tier_assigned_by character varying(255),
    br_po_required boolean,
    br_tax_exempt boolean,
    br_credit_hold boolean,
    br_auto_pay_enabled boolean,
    br_payment_terms character varying(100),
    br_credit_limit numeric(19,4),
    br_currency character varying(3),
    br_invoice_delivery_method character varying(50),
    br_billing_address_id uuid,
    br_discount_policy_ref character varying(200),
    modified_by character varying(255),
    account_marketing_opt_out boolean DEFAULT false NOT NULL,
    account_marketing_opt_out_at timestamp(6) with time zone,
    lifecycle_stage character varying(20) DEFAULT 'ACTIVE'::character varying NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT commercial_party_lifecycle_stage_chk CHECK (((lifecycle_stage)::text = ANY ((ARRAY['PROSPECT'::character varying, 'ACTIVE'::character varying, 'DORMANT'::character varying])::text[]))),
    CONSTRAINT commercial_party_party_type_check CHECK (((party_type >= 0) AND (party_type <= 2))),
    CONSTRAINT commercial_party_status_check CHECK (((status >= 0) AND (status <= 3))),
    CONSTRAINT commercial_party_tier_check CHECK (((tier >= 0) AND (tier <= 5)))
);

CREATE SEQUENCE public.commercial_party_customer_number_seq
    START WITH 1209047103196
    INCREMENT BY 1
    MINVALUE 1209047103196
    MAXVALUE 2821109907455
    CACHE 1;

CREATE TABLE public.communication_preference (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    version bigint NOT NULL,
    party_id uuid NOT NULL,
    preference_id uuid NOT NULL,
    email_preference character varying(20),
    marketing_preference character varying(20),
    phone_preference character varying(20),
    sms_preference character varying(20),
    update_source character varying(20),
    preferences_note character varying(1000),
    marketing_email_consent character varying(20) DEFAULT 'UNSET'::character varying NOT NULL,
    marketing_sms_consent character varying(20) DEFAULT 'UNSET'::character varying NOT NULL,
    opt_out_reason character varying(30),
    opt_out_at timestamp(6) with time zone,
    quiet_hours_start time without time zone,
    quiet_hours_end time without time zone,
    max_marketing_sends_per_month integer,
    CONSTRAINT comm_pref_marketing_email_consent_chk CHECK (((marketing_email_consent)::text = ANY ((ARRAY['OPT_IN'::character varying, 'OPT_OUT'::character varying, 'UNSET'::character varying])::text[]))),
    CONSTRAINT comm_pref_marketing_sms_consent_chk CHECK (((marketing_sms_consent)::text = ANY ((ARRAY['OPT_IN'::character varying, 'OPT_OUT'::character varying, 'UNSET'::character varying])::text[]))),
    CONSTRAINT comm_pref_opt_out_reason_chk CHECK (((opt_out_reason IS NULL) OR ((opt_out_reason)::text = ANY ((ARRAY['NOT_INTERESTED'::character varying, 'TOO_FREQUENT'::character varying, 'NEVER_SIGNED_UP'::character varying, 'CONTENT_NOT_RELEVANT'::character varying, 'LEGAL_DNC'::character varying, 'OTHER'::character varying])::text[]))))
);

CREATE TABLE public.consent_event (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    consent_event_id uuid NOT NULL,
    party_id uuid NOT NULL,
    channel character varying(20) NOT NULL,
    old_value character varying(20) NOT NULL,
    new_value character varying(20) NOT NULL,
    reason character varying(30),
    source character varying(30) NOT NULL,
    actor character varying(255),
    occurred_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT consent_event_channel_chk CHECK (((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying])::text[]))),
    CONSTRAINT consent_event_new_value_chk CHECK (((new_value)::text = ANY ((ARRAY['OPT_IN'::character varying, 'OPT_OUT'::character varying, 'UNSET'::character varying])::text[]))),
    CONSTRAINT consent_event_old_value_chk CHECK (((old_value)::text = ANY ((ARRAY['OPT_IN'::character varying, 'OPT_OUT'::character varying, 'UNSET'::character varying])::text[]))),
    CONSTRAINT consent_event_source_chk CHECK (((source)::text = ANY ((ARRAY['CSR'::character varying, 'SELF_SERVICE'::character varying, 'UNSUBSCRIBE_LINK'::character varying, 'IMPORT'::character varying, 'API'::character varying, 'SYSTEM'::character varying])::text[])))
);

