    CONSTRAINT contact_role_assignment_role_name_check CHECK (((role_name)::text = ANY (ARRAY[('BILLING'::character varying)::text, ('PAYMENT_AUTHORIZER'::character varying)::text, ('OPERATIONS'::character varying)::text, ('PRIMARY_BUSINESS_CONTACT'::character varying)::text, ('TECHNICAL'::character varying)::text])))
