    occurred_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT customer_interaction_channel_chk CHECK (((channel IS NULL) OR ((channel)::text = ANY ((ARRAY['EMAIL'::character varying, 'SMS'::character varying])::text[])))),
    CONSTRAINT customer_interaction_direction_chk CHECK (((direction)::text = ANY ((ARRAY['OUTBOUND'::character varying, 'INBOUND'::character varying])::text[]))),
    CONSTRAINT customer_interaction_type_chk CHECK (((type)::text = ANY ((ARRAY['CAMPAIGN_SEND'::character varying, 'EMAIL'::character varying, 'SMS'::character varying, 'CALL'::character varying, 'FOLLOW_UP'::character varying, 'NOTE'::character varying, 'WORKORDER_NOTE'::character varying])::text[])))
);

