    CONSTRAINT follow_up_task_type_chk CHECK (((type)::text = ANY ((ARRAY['DECLINED_SERVICE_FOLLOWUP'::character varying, 'SERVICE_DUE_REMINDER'::character varying, 'FLEET_CHECKIN'::character varying, 'CAMPAIGN_RESPONSE'::character varying, 'GENERAL'::character varying])::text[])))
