    CONSTRAINT inquiry_channel_chk CHECK (((channel)::text = ANY ((ARRAY['WEB_FORM'::character varying, 'PHONE'::character varying, 'WALK_IN'::character varying, 'EMAIL'::character varying, 'REFERRAL'::character varying, 'CAMPAIGN'::character varying])::text[]))),
    CONSTRAINT inquiry_contactable_chk CHECK (((email IS NOT NULL) OR (phone IS NOT NULL))),
